/**
 * Font dokumen PDF.
 *
 * pdfmake hanya membawa Roboto, sedangkan dokumen perusahaan memakai
 * Calibri. Yang dipakai di sini adalah Carlito — klon metrik Calibri
 * (lebar karakter identik, bebas lisensi), sehingga tata letak dokumen
 * sama persis dengan versi Word-nya.
 *
 * Font sudah di-subset ke Latin + tanda baca yang dipakai dokumen,
 * jadi ukurannya ~55KB, bukan ~1,7MB.
 */
export const CALIBRI_REGULAR =
  '';

export const CALIBRI_BOLD =
  '';

/**
 * Konfigurasi font + vfs untuk satu dokumen.
 *
 * Sengaja TIDAK menyetel `pdfMake.vfs` global: beberapa helper PDF lain
 * menjalankan `pdfMake.vfs = pdfFonts.vfs` saat modul dimuat, sehingga
 * entri font yang sudah didaftarkan bisa tertimpa dan berkasnya "hilang"
 * dari virtual file system. Hasil fungsi ini dikirim langsung ke
 * `createPdf(dd, layouts, fonts, vfs)`.
 */
export function documentFonts(baseVfs: Record<string, string>) {
  const vfs: Record<string, string> = {
    ...(baseVfs || {}),
    'Calibri-Regular.ttf': CALIBRI_REGULAR,
    'Calibri-Bold.ttf': CALIBRI_BOLD,
  };

  const fonts = {
    Calibri: {
      normal: 'Calibri-Regular.ttf',
      bold: 'Calibri-Bold.ttf',
      // dokumen tidak memakai italic; arahkan ke berkas yang sama
      italics: 'Calibri-Regular.ttf',
      bolditalics: 'Calibri-Bold.ttf',
    },
    // tetap sediakan Roboto sebagai cadangan
    Roboto: {
      normal: 'Roboto-Regular.ttf',
      bold: 'Roboto-Medium.ttf',
      italics: 'Roboto-Italic.ttf',
      bolditalics: 'Roboto-MediumItalic.ttf',
    },
  };

  return { fonts, vfs };
}
